174	/// Wrapper around [DomTree::dominates] to work at instruction level.
175	/// Does `inst1` dominate `inst2` ?
176	fn dominates(context: &Context, dom_tree: &DomTree, inst1: Value, inst2: Value) -> bool {
177	    let block1 = match &context.values[inst1.0].value {
178	        crate::ValueDatum::Argument(arg) => arg.block,
179	        crate::ValueDatum::Constant(_) => {
180	            panic!("Shouldn't be querying dominance info for constants")
181	        }
182	        crate::ValueDatum::Instruction(i) => i.parent,
183	    };
184	    let block2 = match &context.values[inst2.0].value {
185	        crate::ValueDatum::Argument(arg) => arg.block,
186	        crate::ValueDatum::Constant(_) => {
187	            panic!("Shouldn't be querying dominance info for constants")
188	        }
189	        crate::ValueDatum::Instruction(i) => i.parent,
190	    };
191	
192	    if block1 == block2 {
193	        let inst1_idx = block1
194	            .instruction_iter(context)
195	            .position(|inst| inst == inst1)
196	            // Not found indicates a block argument
197	            .unwrap_or(0);
198	        let inst2_idx = block1
199	            .instruction_iter(context)
200	            .position(|inst| inst == inst2)
201	            // Not found indicates a block argument
202	            .unwrap_or(0);
203	        inst1_idx < inst2_idx
204	    } else {
205	        dom_tree.dominates(block1, block2)
206	    }
207	}
